package com.autoops.workflow.controller;import com.autoops.workflow.service.WorkflowExecutionService;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/workflows")public class WorkflowRunController{private final WorkflowExecutionService service;public WorkflowRunController(WorkflowExecutionService s){service=s;}public record RunRequest(Long machineId,Long credentialId){}@PostMapping("/{id}/run")public WorkflowExecutionService.Result run(@PathVariable Long id,@RequestBody RunRequest r){return service.run(id,r.machineId(),r.credentialId());}}
